x=new('00831','Atezolizumab + bevacizumab for HCC','2a',21);p=x['patient'];p.update(therapy_label='Immunotherapy + anti-VEGF therapy',schedule_kind='three_weekly_immunotherapy_anti_vegf',schedule_label='Treatment every three weeks',context_label='First-line advanced or unresectable liver cancer (HCC)',medicines_title='Two medicines with different effects and safety checks',phases_title='Treatment, monitoring and review every three weeks')
p['purpose']='This combination aims to control hepatocellular carcinoma, a cancer that starts in the liver, when it is advanced or cannot be removed and no previous systemic treatment has been given. Atezolizumab helps immune cells recognise cancer; bevacizumab blocks a signal that supports blood-vessel growth.'
p['indication_text']='NCCP 00831a: adults with advanced or unresectable HCC without previous systemic therapy; usual source eligibility includes ECOG 0–1 and Child-Pugh A liver function.'
p['scope_note']='This is the HCC combination, not atezolizumab alone or a lung-cancer chemotherapy combination. Existing liver disease and bleeding risk need review alongside possible immune side effects. Your team assesses each medicine separately.'
p['schedule_summary']='Atezolizumab is given first on Day 1 as an IV infusion or a subcutaneous injection into the thigh, followed by bevacizumab through a vein. Treatment is planned every 21 days while it is helping and side effects remain acceptable.'
p['phases_note']='There is no fixed total number of cycles. Clinical benefit, liver function, bleeding risk, immune effects and your preferences guide treatment. One medicine may be paused or stopped while the other is considered separately by the team.'
p['administration_text']='IV atezolizumab is usually infused over 60 minutes initially and may take 30 minutes later if tolerated. The alternative 1875 mg thigh injection takes about seven minutes. Bevacizumab is still an IV infusion: usually 90 minutes first, then 60 and later 30 minutes if tolerated. Checks, preparation and observation make the whole visit longer.'
p['agents']=[agent('atezolizumab','Atezolizumab','Tecentriq; IV infusion or thigh injection','PD-L1 immune checkpoint inhibitor','Helps immune cells recognise and attack cancer','Blocking PD-L1 can release a brake on the immune response. This may control cancer but can also cause inflammation in healthy organs during treatment or after it stops.','PD-L1 blockade|Immune response increases|Cancer and healthy tissues may be affected'.split('|'),'Carry the immunotherapy alert card. Report new bowel, breathing, skin, hormone, heart, liver, kidney or neurological symptoms promptly.',['Immune inflammation of lungs, bowel, liver, kidneys or skin','Hormone changes, including thyroid, adrenal or pituitary problems and diabetes; replacement may be long term','Rare serious heart, muscle, nerve or brain inflammation','Infusion/injection reactions; delayed immune effects after stopping'],['Breathing / cough','Diarrhoea','Skin / nail changes','Fatigue','Headache','Muscle / joint pain'],['nccp','atezo-smpc']),agent('bevacizumab','Bevacizumab','Avastin or prescribed biosimilar; IV infusion','Anti-VEGF antibody','Blocks a signal for blood-vessel growth','Bevacizumab binds VEGF, reducing signals that help tumours develop blood vessels. It can also affect normal blood vessels, blood pressure, kidney filtration and wound healing.','VEGF signal blocked|Tumour vessel growth reduced|Blood vessels and healing need monitoring'.split('|'),'Report bleeding, severe headache, chest or abdominal pain, leg swelling, reduced urine or poor wound healing. Tell the team before surgery or dental procedures.',['Raised blood pressure; rarely hypertensive crisis or PRES','Protein in urine and kidney injury, including nephrotic syndrome','Bleeding, including serious bleeding from varices','Arterial or venous blood clots','Poor wound healing, bowel perforation or fistula; rare jaw problems','Infusion or allergic reactions'],['Bleeding / bruising','Headache','Urinary symptoms','Muscle / joint pain','Fatigue'],['nccp','bev-smpc'])]
