p['anatomy']=[['brain','Hormones / brain','Atezolizumab','Tiredness, thirst, dizziness or a new headache may need hormone or neurological review.',50,6],['lungs','Lungs','Atezolizumab','New cough or breathlessness needs prompt assessment for lung inflammation and other causes.',61.5,24.7],['heart','Heart','Atezolizumab','Chest pain, palpitations or breathlessness may reflect heart or surrounding-tissue inflammation.',52.5,28.3],['liver','Liver','Atezolizumab / underlying HCC','Yellow eyes, dark urine or blood-test changes need cause assessment; liver disease is not automatically immune hepatitis.',43,33],['kidneys','Kidneys / urine','Both medicines','Reduced urine or swelling needs review; immune kidney inflammation and bevacizumab protein loss require different assessment.',39.5,38.6],['bowel','Bowel','Both medicines','Diarrhoea, blood or pain can indicate immune colitis; sudden severe pain can signal bowel perforation and needs emergency assessment.',50,44.5],['muscles','Skin / nerves / muscles','Atezolizumab','Rash, blisters, weakness, numbness or muscle pain can be immune effects.',37,60.5],['joints','Joints','Atezolizumab','Painful swollen joints may need assessment for inflammatory arthritis.',61,69],['vessels','Blood vessels / healing','Bevacizumab','Bleeding, clots, raised blood pressure or delayed wound healing need prompt review.',61.5,61.5]]
