p['evidence']=dict(title='Evidence in previously untreated unresectable HCC',intro='IMbrave150 compared atezolizumab plus bevacizumab with sorafenib in selected people with HCC and preserved liver function.',population='Previously untreated unresectable HCC, predominantly Child-Pugh A and ECOG 0–1.',combination_label='Atezolizumab + bevacizumab',comparison_label='Sorafenib',metrics=[],interpretation='The combination improved survival and time before cancer progressed in the study population. This does not predict an individual outcome or establish the same benefit for more severe liver dysfunction.',limitations='The trial used IV atezolizumab and excluded important bleeding-risk groups. SC administration is supported by product and NCCP formulation evidence, not a separate HCC survival comparison. Other modern regimens require their own evidence discussion.',source_ids=['imbrave','atezo-smpc'])
