cl=dict(component_rationale='Atezolizumab inhibits PD-L1-mediated immune suppression; bevacizumab inhibits VEGF signalling. The combination has distinct immune, vascular and underlying liver-disease safety domains.',key_points=['NCCP 00831a: first systemic therapy for advanced/unresectable HCC; ECOG 0–1, Child-Pugh A.','Atezolizumab 1200 mg IV or 1875 mg SC then bevacizumab 15 mg/kg IV every 21 days; no dose reductions recommended.','Screen and manage oesophageal varices before treatment; recent bleeding/high-risk untreated varices require review.','HCC hepatitis thresholds depend on the matching baseline transaminase category; current LFTs alone do not establish immune causation.','NCCP Table 3 grading is CTCAE v4.0, not v5.0.','Bevacizumab 2+/3+ dipstick requires timed-protein follow-up; >2 to 4 g/24 h holds, >4 discontinues under NCCP. Nephrotic syndrome has an independent SmPC permanent-stop rule.','Persistent grade-3 hypertension, grade-4 VTE, grade≥3 bleeding, perforation and specified fistulae have distinct actions.','Counts are monitored without importing chemotherapy ANC/platelet dose thresholds.'],patient_selection=dict(treatment_intent='Disease control in previously untreated advanced/unresectable HCC.',disease_and_biomarker_context=[p['indication_text'],'No PD-L1 testing requirement is specified for this HCC indication.'],eligibility_orientation=['Confirm Child-Pugh A, ECOG 0–1, no previous systemic HCC therapy and adequate organ function.','Assess varices, viral hepatitis, ascites, autoimmune disease, immunosuppression, bleeding/clotting and surgery risks.'],important_cautions=['No equivalent efficacy inference for Child-Pugh B/C or untreated high-risk varices.','Laboratory abnormalities require cause assessment; immune attribution is clinical.','The bevacizumab SmPC does not itself list HCC; HCC combination indication is supported by Tecentriq SmPC and NCCP.']),support_summary=[s['text'] for s in p['support']],baseline=['FBC, renal/liver profile, glucose, TFTs, oesophageal-varices screening, dipstick protein and BP/cardiac assessment.','Consider ECHO after chest-wall radiation or anthracycline; INR if indicated.'],before_each_cycle=['FBC, renal/liver profile, glucose and dipstick protein before every cycle.','Blood pressure before each cycle and after treatment; review clinical toxicity and component-specific decisions.'],ongoing=['TFTs every six weeks; other tests and imaging according to clinical need and Consultant plan.','Warfarin: weekly INR until stable dose, then INR before each cycle.','Maintain immune alert and delayed-toxicity follow-up after stopping.'],administration=[p['administration_text'],'Atezolizumab first, bevacizumab second. SC injection sites alternate thighs; avoid red/bruised/tender/hard skin. Maintain the planned three-week interval when rescheduling missed atezolizumab.'],access=['Anaphylaxis treatment facilities and suitable IV access are required even when atezolizumab is SC.','Rapid bevacizumab infusion is a separate off-label/local-policy option; it is not the default schedule here.'],rationale=dict(summary=p['purpose'],setting=p['context_label'],line='First systemic therapy',factors=['Liver function and variceal bleeding risk','Autoimmune/vascular disease, performance status and patient priorities','IV versus SC availability and separate component tolerability'],alternatives=['Discuss current MDT options, trials and supportive care including not proceeding; avoid cross-trial superiority claims.'],limitations=[p['evidence']['limitations'],'NCCP source reconciliation and software tests are not independent clinical approval.'],sources=[dict(label='IMbrave150 updated analysis',url=URL['imbrave'])]))
ev=dict(trial='IMbrave150 updated analysis',population='501 patients with previously untreated unresectable HCC, Child-Pugh A and ECOG 0–1, randomised 336 versus 165.',comparison='Atezolizumab 1200 mg IV plus bevacizumab 15 mg/kg every three weeks versus sorafenib.',applicability=p['evidence']['interpretation'],endpoints=[dict(endpoint='OS',metric='Median overall survival from randomisation; 31 August 2020 data cutoff',intervention_value=19.2,comparator_value=13.4,unit='months',intervention_label='Atezolizumab + bevacizumab',comparator_label='Sorafenib',hr='0.66 (95% CI 0.52–0.85)',interpretation='Updated ITT analysis; median follow-up 15.6 months. Group estimate for the selected first-line HCC population, not an individual prognosis.',analysis_status='Updated published phase III analysis; descriptive p value',sources=[dict(label='Cheng et al. 2022',url=URL['imbrave'])]),dict(endpoint='PFS',metric='Median progression-free survival from randomisation; same 31 August 2020 cutoff',intervention_value=6.9,comparator_value=4.3,unit='months',intervention_label='Atezolizumab + bevacizumab',comparator_label='Sorafenib',hr='0.65 (95% CI 0.53–0.81)',interpretation='Updated whole-trial PFS; do not combine this endpoint with the earlier primary-analysis time point.',analysis_status='Updated published phase III analysis',sources=[dict(label='Cheng et al. 2022',url=URL['imbrave'])])],limitations=[p['evidence']['limitations'],'Variceal bleeding within six months and untreated/incompletely treated varices with bleeding or high bleeding risk were excluded; safety cannot be assumed from screening alone.','Preserved liver function and trial selection limit extrapolation to decompensated cirrhosis.'],harms='In the updated safety population, treatment-related grade 3–4 events occurred in 43% (143/329) with the combination and 46% (72/156) with sorafenib; treatment-related grade-5 events were 2% (6/329) and <1% (1/156). Types of harm differ; similar aggregate percentages do not make the treatments interchangeable.',sources=[dict(label='IMbrave150 updated analysis',url=URL['imbrave']),dict(label='Tecentriq SmPC: HCC eligibility and bleeding precautions',url=URL['atezo-smpc'])],checked=DATE)
